/**
 * NAGDEV PRODUCTS PRIVATE LIMITED — OFFICIAL TECHNICAL DATA SHEET (TDS) GENERATOR
 * Generates an official, publication-ready A4 TDS document with embedded watermark,
 * official company header, guaranteed specification table, and ISO audit stamp.
 */

(function() {
  // Ensure window.getProductById is available
  if (typeof window !== 'undefined' && !window.getProductById) {
    window.getProductById = function(id) {
      if (typeof PRODUCTS_DATABASE !== 'undefined') {
        return PRODUCTS_DATABASE.find(function(p) { return p.id === id; });
      }
      return null;
    };
  }

// ── TDS Generator Function with Embedded LOGO Watermark ───────────────────
  const NPPL_LOGO_B64 = "data:image/png;base64,";

  function downloadProductTDS(productId) {
    const p = window.getProductById(productId);
    if (!p) return;

    let specRowsHtml = '';
    if (p.specs && p.specs.length) {
      const headers = p.headers || ['SR.', 'Test Parameter', 'Specification', 'Test Method'];
      specRowsHtml = `
        <table class="spec-table">
          <thead>
            <tr>
              ${headers.map(h => `<th>${h}</th>`).join('')}
            </tr>
          </thead>
          <tbody>
            ${p.specs.map((row, idx) => `
              <tr style="background:${idx % 2 === 0 ? 'rgba(250,247,242,0.65)' : 'rgba(255,255,255,0.65)'};">
                ${row.map((c, i) => `<td style="${i === 0 ? 'font-weight:bold;text-align:center;' : ''}">${c}</td>`).join('')}
              </tr>
            `).join('')}
          </tbody>
        </table>
      `;
    }

    const tdsHtml = `
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="utf-8">
        <title>Products Portfolio | Nagdev Products — Castor Oil & Derivatives</title>
        <style>
          @page { size: A4 portrait; margin: 12mm 15mm 15mm 15mm; }
          * { box-sizing: border-box; }
          body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            color: #1a1a1a;
            margin: 0;
            padding: 30px;
            background: #ffffff;
            position: relative;
            min-height: 100vh;
          }

          /* ── Centered Visible LOGO Watermark ── */
          .watermark-bg {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%) rotate(-25deg);
            width: 560px;
            max-width: 85vw;
            opacity: 0.18;
            z-index: 0;
            pointer-events: none;
            user-select: none;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }
          .watermark-bg img {
            width: 100%;
            height: auto;
            display: block;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }

          .tds-content {
            position: relative;
            z-index: 1;
            max-width: 820px;
            margin: 0 auto;
          }

          .no-print {
            margin-bottom: 25px;
            padding: 12px 18px;
            background: #f4f0e8;
            border: 1px solid #dcd2bf;
            border-radius: 6px;
            display: flex;
            justify-content: space-between;
            align-items: center;
          }
          .print-btn {
            background: #0b3d1e;
            color: #ffffff;
            border: none;
            padding: 9px 22px;
            font-size: 14px;
            font-weight: 700;
            border-radius: 4px;
            cursor: pointer;
            display: inline-flex;
            align-items: center;
            gap: 8px;
            box-shadow: 0 2px 6px rgba(0,0,0,0.18);
          }
          .print-btn:hover { background: #072813; }

          .header-table {
            width: 100%;
            border-bottom: 2.5px solid #0b3d1e;
            padding-bottom: 12px;
            margin-bottom: 20px;
          }
          .header-logo {
            height: 52px;
            width: auto;
            display: block;
          }
          .header-info {
            text-align: right;
            font-size: 11.5px;
            color: #444;
            line-height: 1.45;
          }
          .tds-badge {
            display: inline-block;
            background: #d4a537;
            color: #0b3d1e;
            font-weight: 700;
            font-size: 10.5px;
            letter-spacing: 0.08em;
            padding: 2px 8px;
            border-radius: 3px;
            text-transform: uppercase;
            margin-bottom: 4px;
          }
          .doc-ref {
            font-family: monospace;
            font-weight: 700;
            color: #0b3d1e;
          }

          .product-title-row {
            margin-bottom: 16px;
          }
          .prod-name {
            font-size: 23px;
            font-weight: 700;
            color: #0b3d1e;
            margin: 0 0 3px 0;
            line-height: 1.2;
          }
          .prod-cat {
            font-size: 12.5px;
            color: #8f6b1e;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
          }

          .meta-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 8px 18px;
            background: rgba(251, 249, 245, 0.7);
            border: 1px solid #e6decb;
            border-radius: 6px;
            padding: 12px 18px;
            font-size: 12px;
            margin-bottom: 18px;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }
          .meta-item {
            display: flex;
            justify-content: space-between;
            border-bottom: 1px dashed rgba(232, 226, 212, 0.8);
            padding-bottom: 4px;
          }
          .meta-lbl { color: #666; font-weight: 500; }
          .meta-val { color: #111; font-weight: 600; text-align: right; }
          .meta-val.mono { font-family: monospace; }

          .section-title {
            font-size: 12.5px;
            font-weight: 700;
            color: #0b3d1e;
            text-transform: uppercase;
            letter-spacing: 0.06em;
            border-bottom: 1.5px solid #d4a537;
            padding-bottom: 4px;
            margin: 18px 0 10px 0;
          }

          .spec-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 11.5px;
            margin-bottom: 16px;
          }
          .spec-table th {
            background: #0b3d1e;
            color: #ffffff;
            padding: 7px 10px;
            text-align: left;
            font-weight: 600;
            border: 1px solid #0b3d1e;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }
          .spec-table td {
            padding: 6px 10px;
            border: 1px solid #dcd2bf;
            color: #222;
          }

          .desc-text {
            font-size: 12px;
            color: #333;
            line-height: 1.55;
            margin: 0 0 12px 0;
          }

          .footer-box {
            margin-top: 30px;
            padding-top: 14px;
            border-top: 1.5px solid #c2b59b;
            font-size: 10.5px;
            color: #555;
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
            line-height: 1.5;
          }
          .footer-left { max-width: 68%; }
          .footer-stamp {
            text-align: right;
            font-size: 10.5px;
            color: #0b3d1e;
            font-weight: 600;
          }

          @media print {
            .no-print { display: none !important; }
            body { padding: 0 !important; background: #ffffff !important; }
            .watermark-bg {
              position: fixed !important;
              top: 50% !important;
              left: 50% !important;
              transform: translate(-50%, -50%) rotate(-25deg) !important;
              width: 580px !important;
              opacity: 0.18 !important;
              display: block !important;
              visibility: visible !important;
              z-index: 0 !important;
              -webkit-print-color-adjust: exact !important;
              print-color-adjust: exact !important;
            }
            .watermark-bg img {
              -webkit-print-color-adjust: exact !important;
              print-color-adjust: exact !important;
            }
            .meta-grid {
              background: rgba(251, 249, 245, 0.45) !important;
              -webkit-print-color-adjust: exact !important;
            }
            .spec-table th {
              background: #0b3d1e !important;
              color: #ffffff !important;
              -webkit-print-color-adjust: exact !important;
            }
            .spec-table td {
              background: rgba(255, 255, 255, 0.35) !important;
              -webkit-print-color-adjust: exact !important;
            }
            .spec-table tr:nth-child(even) td {
              background: rgba(250, 247, 242, 0.5) !important;
              -webkit-print-color-adjust: exact !important;
            }
          }
        </style>
      </head>
      <body>
        <!-- CENTRED EMBEDDED LOGO WATERMARK -->
        <div class="watermark-bg">
          <img src="${NPPL_LOGO_B64}" alt="Nagdev Products Watermark">
        </div>

        <div class="tds-content">
          <div class="no-print">
            <button class="print-btn" onclick="window.print()">
              🖨️ Print / Save as PDF
            </button>
            <span style="font-size:12.5px;color:#555;">
              Nagdev Products Private Limited · Official Product Specification
            </span>
          </div>

          <!-- HEADER WITH LOGO -->
          <table class="header-table">
            <tr>
              <td style="vertical-align:middle;">
                <img src="${NPPL_LOGO_B64}" alt="Nagdev Products" class="header-logo">
              </td>
              <td class="header-info" style="vertical-align:middle;">
                <span class="tds-badge">Official Technical Data Sheet</span><br>
                <strong>Document Ref:</strong> <span class="doc-ref">NPPL-TDS-${p.brandCode || p.id.toUpperCase()}</span><br>
                <strong>Brand Line:</strong> <span style="color:#0b3d1e;font-weight:700;">${p.brandName || p.name}</span><br>
                <strong>Revision Date:</strong> 2026 Edition<br>
                <strong>Origin:</strong> Gujarat, India
              </td>
            </tr>
          </table>

          <div class="product-title-row">
            <div style="font-size:12.5px;font-weight:700;color:#8f6b1e;letter-spacing:0.06em;text-transform:uppercase;margin-bottom:2px;">${p.brandName || ''}</div>
            <h1 class="prod-name">${p.name}</h1>
            <div class="prod-cat">${p.categoryLabel}</div>
          </div>

          <!-- METADATA GRID -->
          <div class="meta-grid">
            <div class="meta-item"><span class="meta-lbl">CAS Number:</span><span class="meta-val mono">${p.casNumber || 'Not Assigned / Proprietary'}</span></div>
            <div class="meta-item"><span class="meta-lbl">Physical Form:</span><span class="meta-val">${p.physicalForm}</span></div>
            <div class="meta-item"><span class="meta-lbl">Typical Colour:</span><span class="meta-val">${p.typicalColour}</span></div>
            <div class="meta-item"><span class="meta-lbl">Raw Material:</span><span class="meta-val">${p.rawMaterial}</span></div>
            <div class="meta-item"><span class="meta-lbl">Shelf Life:</span><span class="meta-val">${p.shelfLife}</span></div>
            <div class="meta-item"><span class="meta-lbl">Country of Origin:</span><span class="meta-val">India (Banaskantha, Gujarat)</span></div>
          </div>

          <!-- SPECIFICATIONS -->
          <div class="section-title">Analytical Parameters &amp; Specifications</div>
          ${specRowsHtml}

          <!-- PACKAGING -->
          <div class="section-title">Standard Packaging &amp; Bulk Logistics</div>
          <p class="desc-text">${p.packing}</p>

          <!-- APPLICATIONS -->
          <div class="section-title">Target Industrial Applications</div>
          <p class="desc-text">${p.application}</p>

          <!-- FOOTER -->
          <div class="footer-box">
            <div class="footer-left">
              <strong>Nagdev Products Private Limited</strong> · Survey No. 301 P-2, Jada-Kotarwada Road, Village – Sardarpura, Post – Ravel, Banaskantha, Gujarat – 385330, India<br>
              Email: info@nagdevproducts.com | Phone: +91 63520 98306 | Web: www.nagdevproducts.com<br>
              <em>Disclaimer: The parameters stated in this document are typical values based on standardized ASTM/AOCS testing. Specifications are subject to customary manufacturing tolerances.</em>
            </div>
            <div class="footer-stamp">
              Nagdev Products Pvt. Ltd.<br>
              Quality Assurance Department
            </div>
          </div>
        </div>
      </body>
      </html>
    `;

    const printWin = window.open('', '_blank');
    if (printWin) {
      printWin.document.write(tdsHtml);
      printWin.document.close();
    } else {
      window.showToast('Please allow popups to open the Technical Data Sheet.');
    }
  }

  if (typeof window !== 'undefined') {
    window.downloadProductTDS = downloadProductTDS;
  }
})();
